dtsPropsFor.Button:
/** Visual style. Default 'primary'. */
  variant?: 'primary' | 'accent' | 'secondary' | 'ghost' | 'danger';
  /** Control size. Default 'md'. */
  size?: 'sm' | 'md' | 'lg';
  children?: React.ReactNode;
  /** Plus all native <button> attributes (onClick, type, disabled, …). */
  [prop: string]: unknown;

dtsPropsFor.Input:
/** Standard text field. Accepts all native <input> attributes. */
  type?: string;
  value?: string | number;
  placeholder?: string;
  disabled?: boolean;
  onChange?: React.ChangeEventHandler<HTMLInputElement>;
  className?: string;
  [prop: string]: unknown;

dtsPropsFor.Textarea:
/** Multi-line text field. Accepts all native <textarea> attributes. */
  value?: string;
  placeholder?: string;
  rows?: number;
  disabled?: boolean;
  onChange?: React.ChangeEventHandler<HTMLTextAreaElement>;
  className?: string;
  [prop: string]: unknown;

dtsPropsFor.Select:
/** Styled native select. Pass <option> children. Accepts all native <select> attributes. */
  value?: string | number;
  disabled?: boolean;
  onChange?: React.ChangeEventHandler<HTMLSelectElement>;
  children?: React.ReactNode;
  className?: string;
  [prop: string]: unknown;

dtsPropsFor.Label:
children: React.ReactNode;
  /** Muted trailing hint text, e.g. "opcional". */
  hint?: string;

dtsPropsFor.Field:
/** Field label text. */
  label: string;
  /** Muted trailing hint shown after the label. */
  hint?: string;
  /** The control (Input, Select, Textarea, …). */
  children: React.ReactNode;

dtsPropsFor.Chip:
/** Selected state — fills with ink. */
  active?: boolean;
  onClick?: () => void;
  children: React.ReactNode;

dtsPropsFor.Badge:
children: React.ReactNode;
  /** Semantic color. 'green' maps to the accent-soft violet tint. Default 'gray'. */
  color?: 'gray' | 'green' | 'blue' | 'yellow' | 'red';

dtsPropsFor.Avatar:
/** Image URL; falls back to initials when absent. */
  src?: string | null;
  /** Name — first initial used for the fallback. */
  name?: string | null;
  /** Pixel size (width = height). Default 48. */
  size?: number;
  /** Use the violet accent for the initials fallback (legible on dark surfaces). */
  accent?: boolean;

dtsPropsFor.EmptyState:
/** Primary message. */
  title: string;
  /** Optional muted sub-line. */
  hint?: string;

dtsPropsFor.Stat:
/** Muted label under the value. */
  label: string;
  /** The figure (often a mono-font number). */
  value: React.ReactNode;

dtsPropsFor.Drawer:
/** Controls visibility — renders nothing when false. */
  open: boolean;
  onClose: () => void;
  children: React.ReactNode;

dtsPropsFor.Modal:
/** Controls visibility — renders nothing when false. */
  open: boolean;
  onClose: () => void;
  /** Optional heading. */
  title?: string;
  children: React.ReactNode;

dtsPropsFor.Stepper:
/** Ordered step labels. */
  steps: string[];
  /** Zero-based index of the active step. */
  current: number;

dtsPropsFor.CreatorCard:
/** The creator card payload (from the search/match API). */
  item: {
    id: string;
    username: string;
    name: string | null;
    avatar: string | null;
    headline: string | null;
    country: string | null;
    contentType: string | null;
    niches: string[];
    maxFollowers: number;
    maxEngagement: number;
    verified: boolean;
    topAccounts: { platform: string; followers: number; engagementRate: number | null; verified: boolean; audienceTopCountry: string | null }[];
  };
  onClick?: () => void;
  /** Extra badge shown by the handle (e.g. a match score). */
  extraBadge?: React.ReactNode;
  /** Optional footer region under the card body. */
  footer?: React.ReactNode;

dtsPropsFor.CreatorFilters:
/** Current filter state (controlled). */
  value: {
    niches: string[];
    country: string;
    platform: string;
    followersMin: string;
    engagementMin: string;
    audienceCountry: string;
  };
  /** Called with the next full state on any change. */
  onChange: (next: CreatorFiltersProps['value']) => void;

dtsPropsFor.ShareKit:
/** Public username to build the share link/QR for. */
  username: string;
  /** 'button' opens a share Modal; 'card' renders an inline share panel. Default 'button'. */
  variant?: 'button' | 'card';

dtsPropsFor.AudienceEditor:
/** The creator's social account whose audience breakdown is edited. */
  account: {
    id: string;
    platform: string;
    [prop: string]: unknown;
  };
